SELECT COUNT(DISTINCT L.TITULO COLLATE utf8mb4_0900_ai_ci) N, COUNT(DISTINCT CASE WHEN N.ID IS NOT NULL THEN L.TITULO COLLATE utf8mb4_0900_ai_ci END) PEND, COUNT(DISTINCT CASE WHEN N.ID IS NULL AND NULLIF(L.AUTOR, '') IS NOT NULL THEN L.TITULO COLLATE utf8mb4_0900_ai_ci END) COM_AUTOR FROM LIVROS_INDICADOS L LEFT JOIN LIVROS_NOMES N ON N.NOME = L.TITULO COLLATE utf8mb4_0900_ai_ci WHERE N.ID IS NULL OR N.ESTADO = 'PENDENTE'